export const BUILDINGS={tower:{name:'箭塔',cost:10,desc:'自动攻击敌人；核心光环内强化',hp:330},relay:{name:'星火中继',cost:12,desc:'接入核心后延伸光环，并发射星火',hp:270},farm:{name:'风车农庄',cost:8,desc:'每次守夜成功额外获得 4 金币',hp:230}};
